// FindGame retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindGame(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*Game, error) {
	if len(cols) == 0 {
		return Games.Query(
			SelectWhere.Games.ID.EQ(IDPK),
		).One(ctx, exec)
	}

	return Games.Query(
		SelectWhere.Games.ID.EQ(IDPK),
		sm.Columns(Games.Columns().Only(cols...)),
	).One(ctx, exec)
}

// GameExists checks the presence of a single record by primary key
func GameExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return Games.Query(
		SelectWhere.Games.ID.EQ(IDPK),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after Game is retrieved from the database
func (o *Game) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Games.AfterSelectHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Games.AfterInsertHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, GameSlice{o})
	}

	return err
}

// PrimaryKeyVals returns the primary key values of the Game
func (o *Game) PrimaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *Game) pkEQ() dialect.Expression {
	return sqlite.Quote("game", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.Writer, d bob.Dialect, start int) ([]any, error) {
		return o.PrimaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Game
func (o *Game) Update(ctx context.Context, exec bob.Executor, s *GameSetter) error {
	v, err := Games.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single Game record with an executor
func (o *Game) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := Games.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the Game using the executor
func (o *Game) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Games.Query(
		SelectWhere.Games.ID.EQ(o.ID),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

// AfterQueryHook is called after GameSlice is retrieved from the database
func (o GameSlice) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Games.AfterSelectHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeInsert:
		ctx, err = Games.AfterInsertHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeUpdate:
		ctx, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeDelete:
		ctx, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, o)
	}

	return err
}

func (o GameSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return sqlite.Raw("NULL")
	}

	return sqlite.Quote("game", "id").In(bob.ExpressionFunc(func(ctx context.Context, w io.Writer, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.PrimaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o GameSlice) copyMatchingRows(from ...*Game) {
	for i, old := range o {
		for _, new := range from {
			if new.ID != old.ID {
				continue
			}
			new.R = old.R
			o[i] = new
			break
		}
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o GameSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Games.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Game:
				o.copyMatchingRows(retrieved)
			case []*Game:
				o.copyMatchingRows(retrieved...)
			case GameSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Game or a slice of Game
				// then run the AfterUpdateHooks on the slice
				_, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o GameSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Games.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Game:
				o.copyMatchingRows(retrieved)
			case []*Game:
				o.copyMatchingRows(retrieved...)
			case GameSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Game or a slice of Game
				// then run the AfterDeleteHooks on the slice
				_, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

func (o GameSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals GameSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Games.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o GameSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Games.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o GameSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Games.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

type gameJoins[Q dialect.Joinable] struct {
	typ         string
	GameServers func(context.Context) modAs[Q, gameServerColumns]
	Logs        func(context.Context) modAs[Q, logColumns]
}

func (j gameJoins[Q]) aliasedAs(alias string) gameJoins[Q] {
	return buildGameJoins[Q](buildGameColumns(alias), j.typ)
}

func buildGameJoins[Q dialect.Joinable](cols gameColumns, typ string) gameJoins[Q] {
	return gameJoins[Q]{
		typ:         typ,
		GameServers: gamesJoinGameServers[Q](cols, typ),
		Logs:        gamesJoinLogs[Q](cols, typ),
	}
}

func gamesJoinGameServers[Q dialect.Joinable](from gameColumns, typ string) func(context.Context) modAs[Q, gameServerColumns] {
	return func(ctx context.Context) modAs[Q, gameServerColumns] {
		return modAs[Q, gameServerColumns]{
			c: GameServerColumns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.Name().As(to.Alias())).On(
						to.GameID.EQ(from.ID),
					))
				}

				return mods
			},
		}
	}
}

func gamesJoinLogs[Q dialect.Joinable](from gameColumns, typ string) func(context.Context) modAs[Q, logColumns] {
	return func(ctx context.Context) modAs[Q, logColumns] {
		return modAs[Q, logColumns]{
			c: LogColumns,
			f: func(to logColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Logs.Name().As(to.Alias())).On(
						to.GameID.EQ(from.ID),
					))
				}

				return mods
			},
		}
	}
}

// GameServers starts a query for related objects on game_server
func (o *Game) GameServers(mods ...bob.Mod[*dialect.SelectQuery]) GameServersQuery {
	return GameServers.Query(append(mods,
		sm.Where(GameServerColumns.GameID.EQ(sqlite.Arg(o.ID))),
	)...)
}

func (os GameSlice) GameServers(mods ...bob.Mod[*dialect.SelectQuery]) GameServersQuery {
	PKArgs := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgs[i] = sqlite.ArgGroup(o.ID)
	}

	return GameServers.Query(append(mods,
		sm.Where(sqlite.Group(GameServerColumns.GameID).In(PKArgs...)),
	)...)
}

// Logs starts a query for related objects on log
func (o *Game) Logs(mods ...bob.Mod[*dialect.SelectQuery]) LogsQuery {
	return Logs.Query(append(mods,
		sm.Where(LogColumns.GameID.EQ(sqlite.Arg(o.ID))),
	)...)
}

func (os GameSlice) Logs(mods ...bob.Mod[*dialect.SelectQuery]) LogsQuery {
	PKArgs := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgs[i] = sqlite.ArgGroup(o.ID)
	}

	return Logs.Query(append(mods,
		sm.Where(sqlite.Group(LogColumns.GameID).In(PKArgs...)),
	)...)
}

func (o *Game) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServers":
		rels, ok := retrieved.(GameServerSlice)
		if !ok {
			return fmt.Errorf("game cannot load %T as %q", retrieved, name)
		}

		o.R.GameServers = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Game = o
			}
		}
		return nil
	case "Logs":
		rels, ok := retrieved.(LogSlice)
		if !ok {
			return fmt.Errorf("game cannot load %T as %q", retrieved, name)
		}

		o.R.Logs = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Game = o
			}
		}
		return nil
	default:
		return fmt.Errorf("game has no relationship %q", name)
	}
}

func ThenLoadGameGameServers(queryMods ...bob.Mod[*dialect.SelectQuery]) sqlite.Loader {
	return sqlite.Loader(func(ctx context.Context, exec bob.Executor, retrieved any) error {
		loader, isLoader := retrieved.(interface {
			LoadGameGameServers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
		})
		if !isLoader {
			return fmt.Errorf("object %T cannot load GameGameServers", retrieved)
		}

		err := loader.LoadGameGameServers(ctx, exec, queryMods...)

		// Don't cause an issue due to missing relationships
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}

		return err
	})
}

// LoadGameGameServers loads the game's GameServers into the .R struct
func (o *Game) LoadGameGameServers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.GameServers = nil

	related, err := o.GameServers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Game = o
	}

	o.R.GameServers = related
	return nil
}

// LoadGameGameServers loads the game's GameServers into the .R struct
func (os GameSlice) LoadGameGameServers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		o.R.GameServers = nil
	}

	for _, o := range os {
		for _, rel := range gameServers {
			if o.ID != rel.GameID {
				continue
			}

			rel.R.Game = o

			o.R.GameServers = append(o.R.GameServers, rel)
		}
	}

	return nil
}

